#[derive(Debug, Clone, Deserialize)]
pub struct Content {
    pub source_commit: String,
    pub goods: Vec<GoodDef>,
    pub ships: Vec<ShipDef>,
    pub ports: Vec<PortDef>,
    pub routes: Vec<RouteDef>,
    pub captains: Vec<CaptainDef>,
    pub seasons: Vec<SeasonDef>,
    pub factions: Vec<FactionDef>,
    pub pirate_captains: Vec<PirateCaptainDef>,
    pub contracts: Vec<ContractDef>,
    #[serde(default)]
    pub armor: Vec<ArmorDef>,
    #[serde(default)]
    pub melee_weapons: Vec<MeleeWeaponDef>,
    #[serde(default)]
    pub ranged_weapons: Vec<RangedWeaponDef>,
    #[serde(default)]
    pub fighting_styles: Vec<FightingStyleDef>,
    pub skills: SkillCatalog,
    pub companions: CompanionCatalog,
    pub merchants: Vec<MerchantDef>,
    pub officer_names: OfficerNames,
    pub style_masters: Vec<StyleMasterDef>,
    pub campaign: CampaignCatalog,
}

pub const REGIONS: [&str; 5] = [
    "Mediterranean",
    "North Atlantic",
    "West Africa",
    "East Indies",
    "South Seas",
];

pub fn content() -> &'static Content {
    static CONTENT: OnceLock<Content> = OnceLock::new();
    CONTENT.get_or_init(|| {
        serde_json::from_str(include_str!("../data/content.json"))
            .expect("embedded Portlight content JSON")
    })
}

impl Content {
    pub fn good(&self, id: &str) -> Option<&GoodDef> {
        self.goods.iter().find(|g| g.id == id)
    }

    pub fn ship(&self, id: &str) -> Option<&ShipDef> {
        self.ships.iter().find(|s| s.id == id)
    }

    pub fn captain(&self, id: &str) -> Option<&CaptainDef> {
        self.captains.iter().find(|c| c.id == id)
    }

    pub fn port(&self, id: &str) -> Option<&PortDef> {
        self.ports.iter().find(|p| p.id == id)
    }

    pub fn season_profile(&self, region: &str, day: i64) -> Option<&SeasonDef> {
        let season = season_name(day);
        self.seasons
            .iter()
            .find(|s| s.region == region && s.season == season)
    }

    pub fn factions_in(&self, region: &str) -> Vec<&FactionDef> {
        self.factions
            .iter()
            .filter(|f| f.territory_regions.iter().any(|r| r == region))
            .collect()
    }

    pub fn captains_in_faction(&self, faction_id: &str) -> Vec<&PirateCaptainDef> {
        self.pirate_captains
            .iter()
            .filter(|c| c.faction_id == faction_id)
            .collect()
    }

    pub fn pirate(&self, id: &str) -> Option<&PirateCaptainDef> {
        self.pirate_captains.iter().find(|c| c.id == id)
    }

    pub fn faction(&self, id: &str) -> Option<&FactionDef> {
        self.factions.iter().find(|f| f.id == id)
    }

    pub fn armor(&self, id: &str) -> Option<&ArmorDef> {
        self.armor.iter().find(|a| a.id == id)
    }

    pub fn melee_weapon(&self, id: &str) -> Option<&MeleeWeaponDef> {
        self.melee_weapons.iter().find(|w| w.id == id)
    }

    pub fn ranged_weapon(&self, id: &str) -> Option<&RangedWeaponDef> {
        self.ranged_weapons.iter().find(|w| w.id == id)
    }

    pub fn fighting_style(&self, id: &str) -> Option<&FightingStyleDef> {
        self.fighting_styles.iter().find(|s| s.id == id)
    }

    pub fn skill(&self, id: &str) -> Option<&SkillDef> {
        self.skills.skills.iter().find(|skill| skill.id == id)
    }

    pub fn skill_by_name(&self, name: &str) -> Option<&SkillDef> {
        let name = name.to_lowercase();
        self.skills
            .skills
            .iter()
            .find(|skill| skill.name.to_lowercase() == name)
    }

    /// Trainers at `port_id`, in catalog order. `skill_id` filters further.
    pub fn trainers_at(&self, port_id: &str, skill_id: Option<&str>) -> Vec<&SkillTrainerDef> {
        self.skills
            .trainers
            .iter()
            .filter(|trainer| trainer.port_id == port_id)
            .filter(|trainer| skill_id.is_none_or(|id| trainer.skill_id == id))
            .collect()
    }

    pub fn blacksmith_effect(&self, level: i64) -> &BlacksmithEffectDef {
        let key = level.min(3);
        self.skills
            .blacksmith_effects
            .iter()
            .find(|effect| effect.level == key)
            .or_else(|| {
                self.skills
                    .blacksmith_effects
                    .iter()
                    .find(|effect| effect.level == 0)
            })
            .expect("blacksmith effects")
    }

    pub fn companion(&self, id: &str) -> Option<&CompanionDef> {
        self.companions
            .companions
            .iter()
            .find(|companion| companion.id == id)
    }

    pub fn companion_role(&self, id: &str) -> Option<&CompanionRoleDef> {
        self.companions.roles.iter().find(|role| role.id == id)
    }

    pub fn morale_reaction(&self, trigger: &str) -> Option<&MoraleReactionDef> {
        self.companions
            .morale_reactions
            .iter()
            .find(|row| row.trigger == trigger)
    }

    pub fn personality_modifier(&self, personality: &str) -> Option<&PersonalityModDef> {
        self.companions
            .personality_modifiers
            .iter()
            .find(|row| row.personality == personality)
    }

    pub fn merchant(&self, id: &str) -> Option<&MerchantDef> {
        self.merchants.iter().find(|merchant| merchant.id == id)
    }

    pub fn merchants_at(&self, port_id: &str) -> Vec<&MerchantDef> {
        self.merchants
            .iter()
            .filter(|merchant| merchant.port_id == port_id)
            .collect()
    }

    /// Region name pool. Unknown regions use the Mediterranean list, matching
    /// `generate_officer_name`.
    pub fn officer_pool(&self, region: &str) -> &[String] {
        self.officer_names
            .regions
            .iter()
            .find(|pool| pool.region == region)
            .or_else(|| self.officer_names.regions.first())
            .map(|pool| pool.names.as_slice())
            .unwrap_or(&[])
    }

    pub fn styles_at(&self, port_id: &str) -> Vec<&FightingStyleDef> {
        self.fighting_styles
            .iter()
            .filter(|style| style.training_port_ids.iter().any(|id| id == port_id))
            .collect()
    }

    pub fn masters_at(&self, port_id: &str) -> Vec<&StyleMasterDef> {
        self.style_masters
            .iter()
            .filter(|master| master.port_id == port_id)
            .collect()
    }

    pub fn milestone(&self, id: &str) -> Option<&MilestoneSpecDef> {
        self.campaign.milestones.iter().find(|spec| spec.id == id)
    }
}

pub fn season_name(day: i64) -> &'static str {
    let day_in_year = (day - 1).rem_euclid(360) + 1;
    if day_in_year <= 90 {
        "spring"
    } else if day_in_year <= 180 {
        "summer"
    } else if day_in_year <= 270 {
        "autumn"
    } else {
        "winter"
    }
}

pub fn upgrade_slots(ship_class: &str) -> i64 {
    match ship_class {
        "sloop" => 2,
        "cutter" => 3,
        "brigantine" => 4,
        "galleon" => 5,
        "man_of_war" => 6,
        _ => 2,
    }
}

pub fn ship_class_rank(template_id: &str) -> i64 {
    const ORDER: [&str; 5] = ["sloop", "cutter", "brigantine", "galleon", "man_of_war"];
    for (rank, name) in ORDER.iter().enumerate() {
        if template_id.contains(name) {
            return rank as i64;
        }
    }
    0
}

pub fn class_rank(class_name: &str) -> i64 {
    match class_name {
        "sloop" => 0,
        "cutter" => 1,
        "brigantine" => 2,
        "galleon" => 3,
        "man_of_war" => 4,
        _ => 0,
    }
}
